type CodeModeShape1 = ({
  // Chunk identifier included when the response reports one.
  chunk_id?: string;
  // Command process state, independent of the exec cell. Unknown explicitly means no live handle or terminal outcome is available.
  execution_state: "running" | "exited" | "unknown";
  // Terminal exit code; null when still running or when the exit code is unavailable. Consult execution_state.
  exit_code: number /* integer */ | null;
  // Approximate token count before output truncation.
  original_token_count?: number /* integer */;
  original_token_count_is_approximate?: boolean;
  // Command output text, possibly truncated.
  output: string;
  output_complete: boolean;
  output_decoding_notice?: string;
  output_reduced: boolean;
  pending_deferred_completions?: Array<string>;
  process_exited: boolean;
  // Cumulative bytes retained in the raw output artifact.
  raw_output_artifact_bytes?: number /* integer */;
  // Artifact persistence failure, when retention was unavailable.
  raw_output_artifact_error?: string;
  // Opaque retained-output locator accepted verbatim as read_tool_output.artifact_id.
  raw_output_artifact_id?: string;
  raw_output_artifact_retention_limit_hit: boolean;
  raw_output_artifact_retention_limit_reason?: string;
  // First omitted source line range, when its coordinates are known in raw_output_artifact_id.
  recovery_selector?: { end: number /* integer; minimum: 1 */; kind: "lines"; start: number /* integer; minimum: 1 */; };
  // One pre-execution read-only equivalent repair applied to the command.
  repair?: string;
  session_capabilities?: { cancellation: boolean; interrupt: boolean; polling: boolean; stdin: boolean; };
  // Continuation handle for write_stdin. If execution_state is exited, use it to drain pending output; it does not mean the process is still running.
  session_id?: number /* integer */;
  validation?: { coverage_status: "unverified"; covered_paths: Array<string>; };
  // Elapsed wall time spent waiting for output in seconds.
  wall_time_seconds: number;
}) & ({ execution_state?: "running"; exit_code?: null; output_complete?: false; process_exited?: false; session_id: unknown; } | { execution_state?: "exited"; process_exited?: true; } | { execution_state?: "unknown"; exit_code?: null; output_complete?: false; process_exited?: false; } /* unprojected keyword: not */) /* oneOf: exactly one branch must match */;
type CodeModeShape2 = {
  // Match ASCII letters without regard to case; defaults to false. Non-ASCII bytes remain exact.
  case_insensitive?: boolean;
  // Lines of context to include in returned exact line selectors; defaults to 3 and is capped at 20.
  context_lines?: CodeModeShape3;
  kind: "search";
  // Maximum matches to index; defaults to 20 and is capped at 100.
  max_results?: CodeModeShape4;
  // Fixed string to find, case-sensitive unless case_insensitive is true; at most 1024 UTF-8 bytes.
  query: string;
  // Zero-based byte at which to begin searching.
  start_byte?: CodeModeShape3;
};
type CodeModeShape3 = number /* integer; minimum: 0; maximum: 9007199254740991 */;
type CodeModeShape4 = number /* integer; minimum: 1; maximum: 9007199254740991 */;
type CodeModeShape5 = {
  // Inclusive last line.
  end: CodeModeShape4;
  kind: "lines";
  // One-based first line.
  start: CodeModeShape4;
};
type CodeModeShape6 = {
  // Exclusive end byte.
  end: CodeModeShape3;
  kind: "bytes";
  // Zero-based start byte.
  start: CodeModeShape3;
};
type CodeModeToolSearchResult = { execution: "client"; omitted_result_count: number /* integer; minimum: 0 */ | null; status: "completed" | "incomplete" | "aborted"; tools: unknown[]; };
type ToolCallOptions = { timeout_ms?: number };
declare const tools: {
tool_search(args: {
  // Maximum number of tools to return and activate. Choose the smallest useful limit to avoid loading unrelated schemas. Must be an integer from 1 through 64. Defaults to 8.
  limit?: number /* integer; minimum: 1; maximum: 64 */;
  // Short search terms or an exact name for deferred tools; omit unrelated task context. Must contain non-whitespace text and must not exceed 4,096 UTF-8 bytes.
  query: string;
}, options?: ToolCallOptions): Promise<CodeModeToolSearchResult>;
exec_command(args: ({
  // Arguments for `program`, excluding the program name.
  args?: Array<string>;
  // Shell script to execute in the user's default shell. Prefer this for every command, including pipelines, redirection, shell expansion, compound statements, and builtins.
  cmd?: string;
  // Output token budget, capped at 10000 tokens (8000 inside exec). Zero returns only execution controls.
  max_output_tokens?: CodeModeShape3;
  // Executable to launch directly, bypassing the shell. Use only when `cmd` cannot express the command.
  program?: string;
  // Plain PowerShell script that Codex encodes at runtime. Use only when `cmd` quoting cannot express the script.
  script_body?: string;
  // Shell binary to launch. Defaults to the user's default shell.
  shell?: string;
  // Maximum time without stdout or stderr before cancellation, including between polls. Defaults to 60000 ms; exec_command disables this default for recognized long-running validation, build, install, and discovery commands. Set zero to disable or increase for intentionally quiet or interactive commands. This is not a total runtime limit.
  stall_timeout_ms?: CodeModeShape3;
  // True allocates a PTY for the command; false or omitted uses plain pipes.
  tty?: boolean;
  // Working directory for the command. Defaults to the turn cwd.
  workdir?: string;
  // Wait before yielding output. Defaults to 30000 ms for recognized validation, build, install, and discovery commands (including command chains), and 2000 ms otherwise (10000 ms inside `exec`); explicit values are clamped to 250-300000 ms. On Windows, waits are floored to 2000 ms only while the executor is not ready; commands that finish sooner return immediately. Nested calls may yield up to 2000 ms before their wrapper deadline to return a live session handle.
  yield_time_ms?: number /* integer; minimum: 250; maximum: 300000 */;
}) & ({ cmd: unknown; [key: string]: unknown; } | { program: unknown; [key: string]: unknown; } | { script_body: unknown; [key: string]: unknown; }), options?: ToolCallOptions): Promise<CodeModeShape1>;
write_stdin(args: {
  // Bytes to write to stdin. Defaults to empty, which polls without writing.
  chars?: string;
  // Output token budget. Defaults to a coherent packet of up to 10000 tokens; failure/timeout and high-signal diagnostics use up to 10000 and 10000 tokens respectively; larger requests may be capped by policy. Zero requests a zero-token text budget; command lifecycle and recovery metadata are still returned.
  max_output_tokens?: CodeModeShape3;
  // Identifier of the running unified exec session.
  session_id: number /* integer; minimum: 0; maximum: 4294967295 */;
  // Wait before yielding output. Non-empty writes default to 250 ms and cap at 30000 ms. Empty polls default to 300000 ms and cap at 300000 ms; waits below 5000 ms are honored down to 250 ms only when new output is pending, otherwise a 5000 ms floor applies. A wait deadline does not terminate the process.
  yield_time_ms?: number /* integer; minimum: 250; maximum: 300000 */;
}, options?: ToolCallOptions): Promise<CodeModeShape1>;
read_tool_output(args: {
  // Opaque UUID from the original tool projection.
  artifact_id: string;
  // Compatibility byte budget, capped at 16384.
  max_bytes?: CodeModeShape4;
  // Exact duplicates and overlapping or adjacent same-kind ranges are normalized into stable canonical source order.
  selectors: Array<CodeModeShape6 | CodeModeShape5 | {
  // Stable section ID advertised by the original projection.
  id: string;
  kind: "section";
} | {
  kind: "json_pointer";
  // RFC 6901 pointer; the empty string selects the root.
  pointer: string;
} | CodeModeShape2 /* oneOf: exactly one branch must match */> /* minItems: 1; maxItems: 64 */;
}, options?: ToolCallOptions): Promise<unknown>;
read_file(args: ({
  // Environment id; omit to use the primary environment.
  environment_id?: string;
  // Legacy alias for path; use only one.
  file_path?: string;
  // Bypass retained-result replay and read current contents, even if dependencies appear unchanged.
  force_fresh?: boolean;
  // Legacy positive line count; defaults to 2000 when offset is supplied.
  limit?: number /* integer */;
  // Legacy 1-based starting line; use instead of selectors, defaults to 1.
  offset?: number /* integer */;
  // File path, relative to the environment cwd or absolute, or a `skill:` locator from the skills catalog.
  path?: string;
  // Omit to read the first page immediately. Explicit selectors are exact; oversized selections return child_selectors for the retained snapshot.
  selectors?: Array<CodeModeShape6 | CodeModeShape5 | CodeModeShape2 /* oneOf: exactly one branch must match */> /* minItems: 1; maxItems: 64 */;
}) & ({ path: unknown; [key: string]: unknown; } | { file_path: unknown; [key: string]: unknown; }) /* oneOf: exactly one branch must match */, options?: ToolCallOptions): Promise<unknown>;
list_files(args: {
  // Omit to use the primary environment.
  environment_id?: string;
  // Traverse hidden directories; default false.
  include_hidden?: boolean;
  // Maximum descendant depth, 0 for an immediate directory listing; default 8.
  max_depth?: number /* integer; minimum: 0 */;
  // Maximum entries examined, including directories; default 2000.
  max_entries?: number /* integer; minimum: 1 */;
  // Directory path, relative to the environment cwd or absolute.
  path: string;
}, options?: ToolCallOptions): Promise<unknown>;
update_plan(args: ({
  // Optional explanation for this update, including blockers or cancelled work. Do not mark unfinished work completed.
  explanation?: string;
  // Complete task checklist, replacing the previous plan. Omitted steps are removed; include every step you want to retain.
  plan?: Array<{
  // Current step status.
  status: "pending" | "in_progress" | "completed";
  // Task step text.
  step: string;
}>;
  // Change only these statuses atomically, preserving step text and omitted steps. Use either set or plan. Omitted explanation is preserved with set.
  set?: Array<{
  // Zero-based index in the latest current_plan.plan.
  index: number /* integer; minimum: 0 */;
  status: "pending" | "in_progress" | "completed";
}> /* minItems: 1 */;
}) & ({ plan: unknown; [key: string]: unknown; } | { set: unknown; [key: string]: unknown; }) /* oneOf: exactly one branch must match */, options?: ToolCallOptions): Promise<{
  // The complete stored checklist after this update.
  current_plan: { explanation: string | null; plan: Array<{
  // Current step status.
  status: "pending" | "in_progress" | "completed";
  // Task step text.
  step: string;
}>; };
  // Whether this created the first plan, revised its step text or order, changed only statuses or explanation, or left the plan unchanged.
  effect: "initial" | "structural_revision" | "status_only" | "no_op";
  message: string;
  // True when this update left the stored plan unchanged; this does not assess progress on the underlying work.
  no_progress: boolean;
}>;
context_checkpoint(args: { active_work: string /* maxLength: 8192 */; answered_questions?: Array<{ answer: string /* maxLength: 8192 */; question: string /* maxLength: 8192 */; }> /* maxItems: 32 */; completed_call_ids: Array<string /* maxLength: 256 */> /* maxItems: 128 */; retained_evidence: Array<string /* maxLength: 256 */> /* maxItems: 32 */; summary: string /* maxLength: 8192 */; }, options?: ToolCallOptions): Promise<unknown>;
apply_patch(input: string, options?: ToolCallOptions): Promise<unknown>;
view_image(args: {
  // Image detail level. Defaults to `high`; use `low` for lower-cost overview inspection. When available, `original` preserves exact resolution.
  detail?: "low" | "high" | "original";
  // Local filesystem path to an image file.
  path: string;
}, options?: ToolCallOptions): Promise<{
  // Image detail hint returned by view_image: `low` for overview inspection, `high` for default resized behavior, or `original` when original resolution is preserved.
  detail: "low" | "high" | "original";
  // Data URL for the loaded image.
  image_url: string;
}>;
};
```

